Q: try...catch needed in async call inside useEffect? A: <p>If you want it uses a named <code>async function</code> declaration with loading/error state, proper error handling via <code>try</code>/<code>catch</code>/<code>finally</code>, and a single <code>fetchData()</code> call:</p>
<pre><code>const [loading, setLoading] = useState(false);
const [error, setError] = useState(&quot;&quot;);

useEffect(() =&gt; {
  async function fetchData() {
    try {
      setLoading(true);
      setError(&quot;&quot;);

      const token = await AsyncStorage.getItem('auth.token');
      // do something
    } catch (e) {
      setError(e instanceof Error ? e.message : &quot;Unknown error&quot;);
    } finally {
      setLoading(false);
    }
  }

  fetchData();
}, []);
</code></pre>
